    /// <summary>
    /// <see cref="ICSharpCompiler"/> on top of the consumer's Roslyn. Thread-safe.
    /// <code>var runner = new CodeRunner(new RoslynCSharpCompiler(), options);</code>
    /// </summary>
    internal sealed class RoslynCSharpCompiler : ICSharpCompiler
    {
        internal const string SnippetFile = "snippet.cs";
        internal const string GeneratedFile = "<generated>";
        internal const string UsingsFile = "<usings>";

        static readonly CSharpParseOptions ParseOptions = new CSharpParseOptions(LanguageVersion.Latest, DocumentationMode.None, SourceCodeKind.Regular);
        static readonly ConcurrentDictionary<string, (DateTime Stamp, MetadataReference Reference)> ReferenceCache =
            new ConcurrentDictionary<string, (DateTime, MetadataReference)>(StringComparer.OrdinalIgnoreCase);

        // CodeRunner passes the same list instance while no assembly loads: resolve it to references once per instance.
        readonly object _referencesLock = new object();
        IReadOnlyList<string>? _lastPaths;
        List<MetadataReference> _lastReferences = new List<MetadataReference>();

        public string CompilerVersion => typeof(CSharpCompilation).Assembly.GetName().Version?.ToString() ?? "unknown";

        public CompileResult Compile(CompileRequest request)
        {
            var trees = new List<SyntaxTree>();
            string entryType, entryMethod;
            SnippetWriter.Output? snippet = null;

            var importable = true; // auto-import can add usings to the agent's code (spec §3.3)
            if (request.EntryType != null)
            {
                trees.Add(FullSource(request.Code, request.Usings, out importable));
                entryType = request.EntryType;
                entryMethod = request.EntryMethod ?? "Main";
            }
            else
            {
                snippet = SnippetWriter.Write(request.Code, request.Usings, request.Parameters, returnLastExpression: true);
                trees.Add(Parse(snippet.Source, GeneratedFile));
                entryType = SnippetWriter.EntryType;
                entryMethod = SnippetWriter.EntryMethod;
            }
            trees.AddRange(request.Includes.Select(include => Parse(include.Text, include.Path)));
            if (request.Guards)
                trees.Add(Parse(ExecutionGuard.Source, ExecutionGuard.FileName));

            var compilation = CSharpCompilation.Create(
                request.AssemblyName,
                trees,
                GetReferences(request.ReferencePaths),
                new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary)
                    .WithAllowUnsafe(true)
                    .WithOptimizationLevel(OptimizationLevel.Debug)
                    .WithAssemblyIdentityComparer(DesktopAssemblyIdentityComparer.Default));

            string? resultType = null;
            if (snippet?.ReturnedExpression is { } span)
            {
                var tailType = TypeAt(compilation, trees[0], span);
                if (tailType?.SpecialType == SpecialType.System_Void)
                {
                    // The trailing expression is a void call: run it as a plain statement, the result is null.
                    var plain = Parse(SnippetWriter.Write(request.Code, request.Usings, request.Parameters, returnLastExpression: false).Source, GeneratedFile);
                    compilation = compilation.ReplaceSyntaxTree(trees[0], plain);
                    trees[0] = plain;
                }
                // Tuples, anonymous types and dynamic have no namespace-qualified name: they stay System.Object.
                else if (tailType != null && tailType.TypeKind != TypeKind.Error && tailType.TypeKind != TypeKind.Dynamic
                    && !tailType.IsTupleType && !tailType.IsAnonymousType && !snippet.HasOtherReturns)
                {
                    resultType = tailType.ToDisplayString(ResultTypeFormat); // the tail is the only result: report its type
                }
            }

            if (request.Guards)
            {
                // The guard calls go in last: the spans above (the result expression) point into the unguarded snippet.
                // Guards change no declaration: every tree is read against the same unguarded compilation (bound once).
                var unguarded = compilation;
                for (var i = 0; i < trees.Count; i++)
                {
                    if (trees[i].FilePath == ExecutionGuard.FileName)
                        continue;
                    var guarded = GuardWriter.Write(trees[i], unguarded);
                    if (guarded == trees[i])
                        continue;
                    compilation = compilation.ReplaceSyntaxTree(trees[i], guarded);
                    trees[i] = guarded;
                }
            }

            // Auto-import adds usings to the agent's own code (generated snippet or full source); includes stay verbatim.
            var result = Emit(compilation, importable ? trees[0] : null, request.Usings);
            result.EntryType = entryType;
            result.EntryMethod = entryMethod;
            result.ResultType = resultType;
            return result;
        }

        /// <summary>`System.Int32`, `System.Collections.Generic.List&lt;System.Int32&gt;`: namespaces, no keyword aliases.</summary>
        static readonly SymbolDisplayFormat ResultTypeFormat = new SymbolDisplayFormat(
            typeQualificationStyle: SymbolDisplayTypeQualificationStyle.NameAndContainingTypesAndNamespaces,
            genericsOptions: SymbolDisplayGenericsOptions.IncludeTypeParameters,
            miscellaneousOptions: SymbolDisplayMiscellaneousOptions.ExpandNullable);

        static SyntaxTree Parse(string text, string path) => CSharpSyntaxTree.ParseText(text, ParseOptions, path, Encoding.UTF8);

        /// <summary>
        /// Full-source code with the request's usings in front (spec §3.2: never the host's defaults), each mapped to its
        /// index like the snippet's (§3.4), the code to its own lines. <paramref name="importable"/> is false when the code
        /// starts with what must precede every using (`#define`, `extern alias`, `global using`): then it stays verbatim.
        /// </summary>
        static SyntaxTree FullSource(string code, IReadOnlyList<string> usings, out bool importable)
        {
            var verbatim = Parse(code, SnippetFile);
            var root = verbatim.GetCompilationUnitRoot();
            importable = root.Externs.Count == 0 && !root.Usings.Any(u => u.GetFirstToken().IsKind(SyntaxKind.GlobalKeyword))
                && !root.GetLeadingTrivia().Any(t => t.IsKind(SyntaxKind.DefineDirectiveTrivia) || t.IsKind(SyntaxKind.UndefDirectiveTrivia));
            if (!importable || usings.Count == 0)
                return verbatim;
            var sb = new StringBuilder();
            for (var i = 0; i < usings.Count; i++)
                sb.Append("#line ").Append(i + 1).Append(" \"").Append(UsingsFile).Append("\"\nusing ").Append(usings[i]).Append(";\n");
            return Parse(sb.Append("#line 1 \"").Append(SnippetFile).Append("\"\n").Append(code).ToString(), SnippetFile);
        }

        static ITypeSymbol? TypeAt(CSharpCompilation compilation, SyntaxTree tree, Microsoft.CodeAnalysis.Text.TextSpan span)
        {
            var node = tree.GetRoot().FindNode(span, getInnermostNodeForTie: true);
            var expression = node as ExpressionSyntax ?? node.FirstAncestorOrSelf<ExpressionSyntax>();
            return expression == null ? null : compilation.GetSemanticModel(tree).GetTypeInfo(expression).Type;
        }

        static CompileResult Emit(CSharpCompilation compilation, SyntaxTree? importable, IReadOnlyList<string> usings)
        {
            using (var image = new MemoryStream())
            using (var symbols = new MemoryStream())
            {
                var emit = compilation.Emit(image, symbols, options: new EmitOptions().WithDebugInformationFormat(DebugInformationFormat.PortablePdb));
                var errors = emit.Diagnostics.Where(d => d.Severity == DiagnosticSeverity.Error).ToList();
                return new CompileResult
                {
                    Success = emit.Success,
                    Image = emit.Success ? image.ToArray() : null,
                    Symbols = emit.Success ? symbols.ToArray() : null,
                    Diagnostics = errors.Select(d => ToDiagnostic(d, usings)).ToList(),
                    UnresolvedNames = errors
                        .Where(d => (d.Id == "CS0246" || d.Id == "CS0103") && importable != null && d.Location.SourceTree == importable
                            && d.Location.GetMappedLineSpan().Path != UsingsFile) // a bad using is no type to import
                        .Select(d => importable!.GetRoot().FindNode(d.Location.SourceSpan, getInnermostNodeForTie: true))
                        .Select(n => n as SimpleNameSyntax ?? n.DescendantNodesAndSelf().OfType<SimpleNameSyntax>().FirstOrDefault())
                        .Where(n => n != null)
                        .Select(n => n!.Identifier.ValueText)
                        .Distinct(StringComparer.Ordinal)
                        .ToList(),
                };
            }
        }

        static CodeDiagnostic ToDiagnostic(Diagnostic d, IReadOnlyList<string> usings)
        {
            var span = d.Location.GetMappedLineSpan();
            var file = span.IsValid ? span.Path ?? "" : "";
            var line = span.IsValid ? span.StartLinePosition.Line + 1 : 0;
            var column = span.IsValid ? span.StartLinePosition.Character + 1 : 0;
            var message = d.GetMessage();
            if (file == UsingsFile && line >= 1 && line <= usings.Count)
            {
                // Not the agent's code: name the using (`usings` = the host's defaults plus the request's own).
                message = $"using '{usings[line - 1]}': {message}";
                file = "usings";
                line = column = 0;
            }
            return new CodeDiagnostic
            {
                Id = d.Id,
                Severity = d.Severity.ToString().ToLowerInvariant(),
                File = file == GeneratedFile ? "" : file,
                Line = line,
                Column = column,
                Message = message,
            };
        }

        List<MetadataReference> GetReferences(IReadOnlyList<string> paths)
        {
            lock (_referencesLock)
            {
                if (ReferenceEquals(paths, _lastPaths))
                    return _lastReferences;
            }

            var list = new List<MetadataReference>(paths.Count);
            foreach (var path in paths)
            {
                DateTime stamp;
                try { stamp = File.GetLastWriteTimeUtc(path); }
                catch (Exception) { continue; }
                if (!ReferenceCache.TryGetValue(path, out var cached) || cached.Stamp != stamp)
                {
                    try { cached = (stamp, MetadataReference.CreateFromFile(path)); }
                    catch (Exception) { continue; } // not a .NET assembly, locked or gone: skip it
                    ReferenceCache[path] = cached;
                }
                list.Add(cached.Reference);
            }

            lock (_referencesLock)
            {
                _lastPaths = paths;
                _lastReferences = list;
            }
            return list;
        }
    }
